-- ============================================
-- LUMA — Thème 2 : LONG 3/3 x4 — Une déclaration à un moment clé
-- ============================================


update scenarios set content = '{"characters": {"alex": "Alex"}, "start_node": "n1", "nodes": {"n1": {"speaker": "alex", "text": "Can you believe it''s been exactly one year since our first date?", "text_fr": "Tu réalises que ça fait exactement un an depuis notre premier rendez-vous ?", "choices": [{"text": "A whole year already — it feels like both forever and no time at all.", "text_fr": "Déjà toute une année — ça semble à la fois une éternité et si peu de temps.", "next": "n2"}, {"text": "I actually planned something special for tonight because of that.", "text_fr": "J''ai en fait prévu quelque chose de spécial pour ce soir à cause de ça.", "next": "n2b"}]}, "n2": {"speaker": "alex", "text": "I know exactly what you mean. This trip feels like the perfect way to celebrate.", "text_fr": "Je sais exactement ce que tu veux dire. Ce voyage semble être la parfaite façon de célébrer.", "choices": [{"text": "It really does. I''m so glad we came here together.", "text_fr": "C''est vraiment le cas. Je suis tellement content(e) qu''on soit venus ici ensemble.", "next": "n3"}]}, "n2b": {"speaker": "alex", "text": "Oh? Now I''m curious, what did you have in mind?", "text_fr": "Oh ? Maintenant je suis curieux, tu avais quoi en tête ?", "choices": [{"text": "You''ll see — let''s just enjoy the sunset first.", "text_fr": "Tu verras — profitons du coucher de soleil d''abord.", "next": "n3"}]}, "n3": {"speaker": "alex", "text": "(You both watch the sunset over the cliffs, the sky turning orange and pink.)", "text_fr": "(Vous regardez tous les deux le coucher de soleil sur les falaises, le ciel devenant orange et rose.)", "choices": [{"text": "This view is honestly breathtaking.", "text_fr": "Cette vue est honnêtement à couper le souffle.", "next": "n4"}, {"text": "(Take a moment of silence to just enjoy being together.)", "text_fr": "(Prends un moment de silence pour juste profiter d''être ensemble.)", "next": "n4"}]}, "n4": {"speaker": "alex", "text": "This year with you has honestly been the best of my life.", "text_fr": "Cette année avec toi a honnêtement été la meilleure de ma vie.", "choices": [{"text": "Same here. I never expected to feel this way about someone.", "text_fr": "Pareil pour moi. Je m''attendais jamais à ressentir ça pour quelqu''un.", "next": "n5"}, {"text": "You''ve changed my life in ways I didn''t know were possible.", "text_fr": "Tu as changé ma vie de façons que je pensais pas possibles.", "next": "n5"}]}, "n5": {"speaker": "alex", "text": "(Takes your hand, looking a little nervous suddenly.) I need to tell you something.", "text_fr": "(Prend ta main, ayant l''air soudain un peu nerveux.) Je dois te dire quelque chose.", "choices": [{"text": "(Feel your heart start racing) Okay... what is it?", "text_fr": "(Sens ton cœur commencer à battre fort) D''accord... c''est quoi ?", "next": "n6"}, {"text": "You''re kind of scaring me — is everything okay?", "text_fr": "Tu me fais un peu peur — tout va bien ?", "next": "n6b"}]}, "n6": {"speaker": "alex", "text": "Everything''s more than okay. I just... I love you. I don''t think I''ve said it clearly enough.", "text_fr": "Tout va plus que bien. Je... je t''aime. Je pense pas te l''avoir dit assez clairement.", "choices": [{"text": "(Feel tears well up) I love you too, so much.", "text_fr": "(Sens les larmes monter) Je t''aime aussi, tellement.", "next": "n7"}, {"text": "(Stunned, but deeply moved) I''ve been wanting to hear that.", "text_fr": "(Stupéfait(e), mais profondément ému(e)) J''attendais d''entendre ça.", "next": "n7"}]}, "n6b": {"speaker": "alex", "text": "No, no — everything''s wonderful, I promise, I''m just nervous.", "text_fr": "Non, non — tout va merveilleusement bien, promis, je suis juste nerveux.", "choices": [{"text": "(Relax a little) Okay, take your time.", "text_fr": "(Te détends un peu) D''accord, prends ton temps.", "next": "n6"}]}, "n7": {"speaker": "alex", "text": "This year has shown me exactly what I want — and it''s a future with you.", "text_fr": "Cette année m''a montré exactement ce que je veux — et c''est un futur avec toi.", "choices": [{"text": "I want that too, more than anything.", "text_fr": "Je veux ça aussi, plus que tout.", "next": "n8"}, {"text": "(Overwhelmed with emotion, just hug them tightly.)", "text_fr": "(Submergé(e) par l''émotion, prends-les dans tes bras fort.)", "next": "n8"}]}, "n8": {"speaker": "alex", "text": "I don''t have a ring or anything planned like that yet — I just needed you to know how I feel.", "text_fr": "J''ai pas de bague ou quoi que ce soit de prévu comme ça encore — j''avais juste besoin que tu saches ce que je ressens.", "choices": [{"text": "That''s more than enough. This moment is perfect exactly as it is.", "text_fr": "C''est plus que suffisant. Ce moment est parfait tel qu''il est.", "next": "n9"}, {"text": "Honestly, that makes it even more special — no expectations, just honesty.", "text_fr": "Honnêtement, ça le rend encore plus spécial — pas d''attentes, juste de l''honnêteté.", "next": "n9"}]}, "n9": {"speaker": "alex", "text": "(Smiles, relieved) I was so nervous you''d think it was too soon or too much.", "text_fr": "(Sourit, soulagé) J''étais tellement nerveux que tu penses que c''était trop tôt ou trop.", "choices": [{"text": "Never too much. This is exactly what I needed to hear too.", "text_fr": "Jamais trop. C''est exactement ce que j''avais besoin d''entendre aussi.", "next": "n10"}]}, "n10": {"speaker": "alex", "text": "So... where do we go from here? What do you want our future to look like?", "text_fr": "Donc... on va où à partir d''ici ? Tu veux quoi pour notre futur ?", "choices": [{"text": "I want to keep building this, one day at a time, with you.", "text_fr": "Je veux continuer à construire ça, un jour à la fois, avec toi.", "next": "n11"}, {"text": "Honestly? I could picture moving in together eventually.", "text_fr": "Honnêtement ? Je pourrais imaginer qu''on emménage ensemble un jour.", "next": "n11"}]}, "n11": {"speaker": "alex", "text": "I love that. Whatever it looks like, I just want it to be with you.", "text_fr": "J''adore ça. Peu importe à quoi ça ressemble, je veux juste que ce soit avec toi.", "choices": [{"text": "Me too. Happy anniversary, I love you.", "text_fr": "Moi aussi. Joyeux anniversaire, je t''aime.", "next": "end_love"}]}, "end_love": {"speaker": "alex", "text": "Happy anniversary. Here''s to many, many more.", "text_fr": "Joyeux anniversaire. Vivement beaucoup, beaucoup d''autres.", "end": true, "ending_label": "Une déclaration d''amour inoubliable 💕🌅"}}}'::jsonb, is_playable = true
where title = 'Une déclaration à un moment clé'
  and theme_id = (select id from scenario_themes where position = 2 and language_id = (select id from languages where code = 'en'));
